'use client';

import { useState, useEffect } from 'react';
import { api } from '@/lib/api';
import { Building2, Plus, X } from 'lucide-react';

export default function DepartmentsPage() {
    const [departments, setDepartments] = useState<any[]>([]);
    const [showForm, setShowForm] = useState(false);
    const [form, setForm] = useState({ name: '', code: '' });

    const load = async () => {
        try {
            const res = await api.get<any[]>('/api/admin/departments');
            if (res.success) setDepartments(res.data);
        } catch (e) { }
    };

    useEffect(() => { load(); }, []);

    const handleCreate = async () => {
        try {
            await api.post('/api/admin/departments', form);
            setShowForm(false);
            setForm({ name: '', code: '' });
            load();
        } catch (e) { }
    };

    return (
        <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 24 }}>
                <div>
                    <h1 style={{ fontSize: 24, fontWeight: 700, color: '#142B34', fontFamily: 'Poppins' }}>Departments</h1>
                    <p style={{ fontSize: 14, color: '#5a6a72' }}>Manage academic departments</p>
                </div>
                <button className="btn-primary" onClick={() => setShowForm(true)}>
                    <Plus size={16} /> Add Department
                </button>
            </div>

            {showForm && (
                <div className="card" style={{ marginBottom: 24, padding: 28 }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 16 }}>
                        <h3 style={{ fontSize: 16, fontWeight: 700 }}>New Department</h3>
                        <button onClick={() => setShowForm(false)} style={{ background: 'none', border: 'none', cursor: 'pointer' }}><X size={18} color="#8a9aa2" /></button>
                    </div>
                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16 }}>
                        <div className="form-group"><label>Name</label><input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="Computer Science" /></div>
                        <div className="form-group"><label>Code</label><input value={form.code} onChange={(e) => setForm({ ...form, code: e.target.value })} placeholder="CS" /></div>
                    </div>
                    <button className="btn-primary" onClick={handleCreate}>Create</button>
                </div>
            )}

            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 16 }}>
                {departments.length === 0 ? (
                    <div className="card" style={{ gridColumn: '1 / -1', textAlign: 'center', padding: 40, color: '#8a9aa2' }}>
                        <Building2 size={40} style={{ margin: '0 auto 12px', opacity: 0.3 }} />
                        <p>No departments yet</p>
                    </div>
                ) : departments.map((d) => (
                    <div key={d.id} className="card" style={{ padding: 24 }}>
                        <div style={{ fontSize: 18, fontWeight: 700, color: '#142B34', marginBottom: 8 }}>{d.name}</div>
                        <code style={{ fontSize: 13, background: '#f3f4f6', padding: '2px 8px', borderRadius: 4 }}>{d.code}</code>
                    </div>
                ))}
            </div>
        </div>
    );
}
